def upgrade_check(package, old, new):
    return {
        'package': package, 'from': old, 'to': new,
        'checks': ['unit tests', 'representative import flow'],
        'rollback': 'restore previous tested resolved set'
    }

plan = upgrade_check('example-library', '1.2.0', '1.2.3')
assert plan['to'] == '1.2.3'
assert 'unit tests' in plan['checks']
